def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = np.full_like(g, bg)
    emit(out, "Start from an empty background canvas; each slanted shape will be rebuilt with its right side straightened.")

    for o in objects(g, bg=bg, diagonal=True):
        y0, x0, y1, x1 = o["box"]
        c = o["colour"]
        # Fixed part: the bottom row of the shape and cells already on its rightmost column.
        for (y, x) in o["cells"]:
            if y == y1 or x == x1:
                out[y, x] = c
        emit(out, f"Colour {c} shape: keep its bottom row and its rightmost-column cells in place (the base and right wall do not move).")
        # Moving part: every other cell shifts one column right, clamped to the shape's right edge.
        for (y, x) in o["cells"]:
            if y != y1 and x != x1:
                out[y, min(x + 1, x1)] = c
        emit(out, f"Colour {c} shape: shift the top bar and both diagonals one column to the right, so the right side becomes a vertical edge at column {x1}.")

    emit(out, "All shapes pushed right against their own right edge; final result.")
    return out
